// Numbers: kcal/protein per option were estimated from standard nutrition
// values of the listed portions (cooked weights; 1 tbsp oil = 120 kcal) and the
// portions were calibrated so any combination lands within ~5% of the plan -
// approximate by design,
// the UI labels them "~" and shows the "may contain errors" note.
// Text: per-language copy of the menu PDFs. `_t` = short name used in the
// daily table / saved meals; the plain key = the full option text.
// Missing languages/keys fall back to English (see newMeText()).

