// בוקר קטנה, סלט גדול עם תוספות שוות). small = ארוחה קטנה בכוונה: מה שהיא משאירה מהיעד מתחלק בין שאר הארוחות (nmSlotExtra).
// פיתת כוסמין = עד 100 קלוריות בכל מקום (לפי בקשה מפורשת, 2026-10-12: "פיתת כוסמין עד 100 קלוריות ותשנה לפי הצורך") - ולכן
