        tip_personal: "התאמה אישית: הכמויות מתייחסות למשקל המזון לאחר בישול/אפייה במידת האפשר. אפשר להחליף מנות חלבון/פחמימה בשוות ערך.",
        tip_spread: "ממרחים: כפית שטוחה של ממרח שוקולד היא כ-40–45 קלוריות, וכפיות גדושות עוברות בקלות 120 קלוריות – כדאי למדוד כפיות שטוחות (או במשקל). חמאת בוטנים טבעית נותנת יותר שומנים בריאים, חלבון ושובע לאורך זמן מממרח שוקולד, ולכן היא עדיפה כנשנוש בין הארוחות. טחינה גולמית מלאה עשירה בברזל ובסידן; בטחינה לבנה רגילה יש הרבה פחות סידן.",
        tip_pita: "פיתת כוסמין: כל המספרים בתפריט הם לפי פיתת כוסמין עד 100 קלוריות (פיתות כוסמין קלות או פיתות ביתיות קטנות). פיתה גדולה ועבה יכולה להגיע ל-200 קלוריות ויותר, אז כדאי לבדוק על האריזה.",
        tip_salad: "ארוחת צהריים: כפית שמן זית מספיקה להקפצה – ובמקום ירקות מבושלים אפשר גם סלט ירקות גדול (עד 300 גרם).",
