        tip_spread: "الدهونات: ملعقة صغيرة مسطّحة من الشوكولاتة القابلة للدهن تعادل نحو 40–45 سعرة، والملاعق الممتلئة تتجاوز بسهولة 120 سعرة – يُفضَّل قياس ملاعق مسطّحة (أو استخدام الميزان). زبدة الفول السوداني الطبيعية تمنح دهونًا صحية وبروتينًا وشبعًا أطول من الشوكولاتة، لذا فهي الأفضل كوجبة خفيفة بين الوجبات. الطحينة الخام الكاملة غنية بالحديد والكالسيوم، أما الطحينة البيضاء العادية ففيها كالسيوم أقل بكثير.",
