        tip_veggies: "Заправки и овощи: Некрахмалистые зеленые овощи практически не ограничены. Учитывайте количество масла и тахини (1 ст. л. масла ≈ 120 ккал).",
        tip_personal: "Индивидуальная адаптация: Порции указаны в готовом (приготовленном/запеченном) виде, где это применимо. Источники белков и углеводов можно заменять на равноценные.",
        tip_spread: "Пасты: Одна чайная ложка шоколадной пасты без горки – это около 40–45 ккал, а ложки с горкой легко дают больше 120 ккал – лучше отмерять ложки без горки (или взвешивать). Натуральная арахисовая паста даёт больше полезных жиров, белка и долгой сытости, чем шоколадная, поэтому она лучше как перекус между приёмами пищи. Цельная сырая тахини богата железом и кальцием; в обычной белой тахини кальция гораздо меньше.",
        tip_pita: "Пита из полбы: все цифры в меню рассчитаны на питу из полбы до 100 ккал (лёгкие питы из полбы или маленькие домашние). Большая толстая пита может доходить до 200 ккал и больше, так что стоит посмотреть на упаковку.",
        tip_salad: "Обед: Для обжаривания достаточно 1 ч. ложки оливкового масла – а вместо тушёных овощей подойдёт и большой овощной салат (до 300 г).",
        drinks_desc: "Кофе, чай, молоко или любой другой напиток – добавляются вручную каждый день (не менее 3 напитков). Все напитки вместе: до ~150 ккал.",
