        tip_water: "Flüssigkeitszufuhr: Trinke täglich mindestens 2–2,5 Liter Wasser (ungesüßter grüner Tee oder Kräutertees eignen sich hervorragend).",
        tip_veggies: "Dressing & Gemüse: Nicht stärkehaltiges grünes Gemüse ist nahezu unbegrenzt erlaubt. Achte auf die Menge an Öl und Tahini (1 EL Öl ≈ 120 kcal).",
        tip_personal: "Individuelle Anpassung: Die Mengenangaben beziehen sich, wo zutreffend, auf das Zubereitungsgewicht. Protein- und Kohlenhydratquellen können durch gleichwertige Optionen ersetzt werden.",
        tip_spread: "Aufstriche: Ein gestrichener Teelöffel Schokoaufstrich hat etwa 40–45 kcal, gehäufte Teelöffel kommen leicht über 120 kcal – besser gestrichene Teelöffel abmessen (oder wiegen). Natürliche Erdnussbutter liefert mehr gesunde Fette, Eiweiß und länger anhaltende Sättigung als Schokoaufstrich und ist deshalb der bessere Snack zwischen den Mahlzeiten. Rohe Vollkorn-Tahini ist reich an Eisen und Kalzium; normale helle Tahini enthält viel weniger Kalzium.",
        tip_pita: "Dinkel-Pita: Alle Zahlen im Menü gelten für eine Dinkel-Pita mit bis zu 100 kcal (leichte Dinkel-Pitas oder kleine selbst gemachte). Eine große, dicke Pita kann 200 kcal und mehr haben – ein Blick auf die Packung lohnt sich.",
