        tip_water: "Maji mwilini: Jaribu kunywa angalau lita 2 hadi 2.5 za maji kila siku (chai ya kijani isiyo na sukari au vinywaji vya mitishamba ni vizuri sana pia).",
        tip_veggies: "Michuzi ya saladi na mboga: Mboga za kijani zisizo na wanga zinaweza kuliwa kwa kiasi karibu kisicho na kikomo. Angalia kiasi cha mafuta na tahini (kijiko kikubwa 1 cha mafuta ≈ kalori 120).",
        tip_personal: "Uwezo wa kubadilika: Vipimo vinarejelea uzito baada ya kupikwa/kuokwa, pale inapohusika. Vyanzo vya protini na wanga vinaweza kubadilishwa kwa vyakula vyenye thamani sawa ya lishe.",
        tip_spread: "Vipako: Kijiko kimoja kidogo kilichosawazishwa cha chokoleti ya kupaka ni takriban kalori 40–45, na vijiko vilivyojaa vinaweza kupita kalori 120 kwa urahisi – pima vijiko vilivyosawazishwa (au tumia mizani). Siagi ya karanga ya asili inatoa mafuta mazuri zaidi, protini na kushiba kwa muda mrefu kuliko chokoleti ya kupaka, hivyo ni kitafunio bora kati ya milo. Tahini mbichi ya ufuta mzima ina madini ya chuma na kalsiamu kwa wingi; tahini nyeupe ya kawaida ina kalsiamu kidogo zaidi.",
        tip_pita: "Pita ya spelt: namba zote kwenye menyu zimehesabiwa kwa pita ya spelt ya hadi kalori 100 (pita nyepesi za spelt au pita ndogo za kutengeneza nyumbani). Pita kubwa na nene inaweza kufikia kalori 200 au zaidi, kwa hiyo ni vizuri kuangalia kifurushi.",
        tip_salad: "Chakula cha mchana: Kijiko 1 kidogo cha mafuta ya zeituni kinatosha kukaanga – na badala ya mboga zilizopikwa, saladi kubwa ya mboga (hadi gramu 300) pia inafaa.",
        drinks_desc: "Kahawa, chai, maziwa au kinywaji kingine chochote – huongezwa kwa mkono kila siku (angalau vinywaji 3). Vinywaji vyote pamoja: hadi ~150 kcal.",
        pdf_title: "Mifano ya Mipango ya Milo ya Kila Siku",
