        tip_veggies: "Овочі та заправки: Некрохмалисті зелені овочі можна вживати практично в необмеженій кількості. Стежте за кількістю олії та тахіні (1 ст. л. олії ≈ 120 ккал).",
        tip_personal: "Гнучкість: Вказані порції відповідають вазі після приготування/запікання, де це доречно. Джерела білків і вуглеводів можна замінювати на інші продукти з подібною харчовою цінністю.",
        tip_spread: "Пасти: Одна чайна ложка шоколадної пасти без гірки – це близько 40–45 ккал, а ложки з гіркою легко дають понад 120 ккал – краще відміряти ложки без гірки (або зважувати). Натуральна арахісова паста дає більше корисних жирів, білка й довшої ситості, ніж шоколадна, тому вона краща як перекус між прийомами їжі. Цільна сира тахіні багата на залізо й кальцій; у звичайній білій тахіні кальцію набагато менше.",
        tip_pita: "Піта зі спельти: усі цифри в меню розраховані на піту зі спельти до 100 ккал (легкі піти зі спельти або маленькі домашні). Велика товста піта може мати 200 ккал і більше, тож варто глянути на упаковку.",
        tip_salad: "Обід: Для обсмажування досить 1 ч. ложки оливкової олії – а замість тушкованих овочів підійде й великий овочевий салат (до 300 г).",
        drinks_desc: "Кава, чай, молоко чи будь-який інший напій – додаються вручну щодня (щонайменше 3 напої). Усі напої разом: до ~150 ккал.",
