        tip_personal: "Ευελιξία: Οι αναγραφόμενες ποσότητες αφορούν το βάρος μετά το μαγείρεμα/ψήσιμο, όπου ισχύει. Οι πηγές πρωτεΐνης και υδατανθράκων μπορούν να αντικατασταθούν με άλλα προϊόντα παρόμοιας διατροφικής αξίας.",
        tip_spread: "Αλείμματα: Ένα κοφτό κουταλάκι πραλίνα σοκολάτας έχει περίπου 40–45 θερμίδες, ενώ τα γεμάτα κουταλάκια ξεπερνούν εύκολα τις 120 – καλύτερα να μετράτε κοφτά κουταλάκια (ή με ζυγαριά). Το φυσικό φυστικοβούτυρο δίνει περισσότερα καλά λιπαρά, πρωτεΐνη και πιο διαρκή κορεσμό από την πραλίνα, γι' αυτό είναι καλύτερο σνακ ανάμεσα στα γεύματα. Το ολικής άλεσης ωμό ταχίνι είναι πλούσιο σε σίδηρο και ασβέστιο· το κοινό λευκό ταχίνι έχει πολύ λιγότερο ασβέστιο.",
