        tip_water: "Hidratare: Încearcă să bei cel puțin 2–2,5 litri de apă pe zi (ceaiul verde fără zahăr sau infuziile din plante sunt, de asemenea, excelente).",
        tip_veggies: "Dressinguri și legume: Legumele verzi fără amidon pot fi consumate în cantități aproape nelimitate. Măsoară cu atenție cantitățile de ulei și tahini (1 lingură de ulei ≈ 120 kcal).",
        tip_personal: "Flexibilitate: Cantitățile menționate se referă la greutatea după gătire/coacere, acolo unde este cazul. Sursele de proteine și carbohidrați pot fi înlocuite cu alte produse cu o valoare nutrițională similară.",
        tip_spread: "Creme tartinabile: O linguriță rasă de cremă de ciocolată are aproximativ 40–45 kcal, iar lingurițele cu vârf trec ușor de 120 kcal – măsoară lingurițe rase (sau folosește un cântar). Untul de arahide natural dă mai multe grăsimi sănătoase, proteine și sațietate mai lungă decât crema de ciocolată, de aceea e o gustare mai bună între mese. Tahiniul crud integral e bogat în fier și calciu; tahiniul alb obișnuit are mult mai puțin calciu.",
        tip_pita: "Pita din spelt: toate cifrele din meniu sunt pentru o pita din spelt de până la 100 kcal (pita ușoară din spelt sau pita mică făcută în casă). O pita mare și groasă poate ajunge la 200 kcal sau mai mult, așa că merită să te uiți pe ambalaj.",
        tip_salad: "Prânz: Pentru sotat ajunge 1 linguriță de ulei de măsline – iar în loc de legume gătite merge și o salată mare de legume (până la 300 g).",
