        tip_personal: "Ìyípadà rọrùn: Ìwọ̀n tí a dárúkọ ń tọ́ka sí ìwúwo lẹ́yìn tí a bá ti sè tàbí yan oúnjẹ náà, níbi tí ó bá yẹ. A lè fi àwọn oúnjẹ mìíràn tí iye oúnjẹ aṣaralóore wọn jọra rọ́pò àwọn orísun amuaradagba àti carbohydrate.",
        tip_spread: "Àwọn ìpara: Ṣíbí kékeré kan tí a dọ́gba ti ṣokoléètì ìpara jẹ́ nǹkan bí kálórì 40–45, ṣíbí tí ó kún bámúbámú sì lè kọjá kálórì 120 ní ìrọ̀rùn – fi ṣíbí tí a dọ́gba wọ̀n ọ́n (tàbí lo òṣùwọ̀n). Bọ́tà ẹ̀pà àdánidá ń fúnni ní ọ̀rá tó dára, èròjà protein àti ìtẹ́lọ́rùn tó pẹ́ ju ṣokoléètì lọ, nítorí náà ó dára jù fún ìpanu láàárín oúnjẹ. Tahini aise tí a ṣe pẹ̀lú èso odindi kún fún irin àti kalsiọ́mù; tahini funfun lásán ní kalsiọ́mù tó kéré púpọ̀.",
        tip_pita: "Pita spelt: gbogbo nọ́ńbà inú àtòjọ oúnjẹ ni a ṣírò fún pita spelt tí kò ju kálórì 100 lọ (pita spelt fífúyẹ́ tàbí pita kékeré tí a ṣe nílé). Pita ńlá tó nípọn lè dé kálórì 200 tàbí jù bẹ́ẹ̀ lọ, nítorí náà ó dáa láti wo àpò rẹ̀.",
        tip_salad: "Oúnjẹ ọ̀sán: Ṣíbí kékeré 1 òróró olifi tó láti dín – àti dípò ẹ̀fọ́ sísè, sálàdì ẹ̀fọ́ ńlá (títí dé gíráàmù 300) náà dára.",
        drinks_desc: "Kọfi, tii, wàrà tàbí ohun mímu mìíràn – a máa ń fi kún un pẹ̀lú ọwọ́ lójoojúmọ́ (ó kéré tán ohun mímu 3). Gbogbo ohun mímu papọ̀: tó ~150 kcal.",
