function newMeText(key) {
    const lang = (typeof currentLang !== 'undefined' && currentLang) || 'en';
    const dict = NEW_ME_TEXT[lang];
    if (dict && dict[key] !== undefined) return dict[key];
    return NEW_ME_TEXT.en[key] !== undefined ? NEW_ME_TEXT.en[key] : key;
}
